/*!
 * genesis-emulator.js
 * -----------------------------------------------------------------------
 * A self-contained, self-mounting Sega Genesis / Mega Drive emulator.
 *
 * Wraps the open-source EmulatorJS engine (github.com/EmulatorJS/EmulatorJS)
 * and its Genesis Plus GX core, both GPL-3.0 licensed. The engine code and
 * compiled WASM core are embedded directly in this file (see the BUNDLE
 * constant at the very bottom). At runtime this makes NO network requests
 * and avoids blob:/data: URLs on its critical load path, serving everything
 * straight from memory instead -- see "ENGINE INJECTION" below for why.
 *
 * This file does not include or distribute any game ROMs. Supply your own
 * legally-obtained ROM file at runtime.
 *
 * -----------------------------------------------------------------------
 * DROP-IN USAGE (e.g. inside an <iframe>)
 * -----------------------------------------------------------------------
 *   <!-- frame.html -->
 *   <script src="genesis-emulator.js"></script>
 *
 * That's it. On load, this script builds its own upload UI (drop zone +
 * file picker) and status log into <body>, and boots the emulator as soon
 * as a ROM is selected. Perfect as the `src` of an <iframe>.
 *
 * -----------------------------------------------------------------------
 * PROGRAMMATIC USAGE (bring your own UI)
 * -----------------------------------------------------------------------
 *   <script>window.GenesisEmulatorNoAutoMount = true;</script>
 *   <script src="genesis-emulator.js"></script>
 *   <script>
 *     GenesisEmulator.init('#my-container');
 *     myFileInput.addEventListener('change', e => GenesisEmulator.loadRom(e.target.files[0]));
 *     GenesisEmulator.on('start', () => console.log('Running!'));
 *   </script>
 *
 * -----------------------------------------------------------------------
 * PUBLIC API
 * -----------------------------------------------------------------------
 *   GenesisEmulator.init(target, options) -> API        Mount the player.
 *     target            CSS selector string or DOM element.
 *     options.playerId      id for the internal player div (default: 'genesis-emulator-player')
 *     options.showStatusLog render a small built-in log panel (default: false)
 *
 *   GenesisEmulator.loadRom(file)                        Boot a ROM (File/Blob).
 *   GenesisEmulator.on(event, callback) -> API            event: 'log' | 'error' | 'start'
 *   GenesisEmulator.getInstance() -> EmulatorJS|null      Underlying engine instance.
 */
(function () {
  'use strict';

  // =========================================================================
  // 1. STATE
  // =========================================================================
  /** @type {{container:?Element, playerDiv:?Element, statusLogEl:?Element,
   *          engineInjected:boolean, instance:?object,
   *          callbacks:{log:?Function, error:?Function, start:?Function}}} */
  const state = {
    container: null,
    playerDiv: null,
    statusLogEl: null,
    engineInjected: false,
    instance: null,
    callbacks: { log: null, error: null, start: null }
  };

  // =========================================================================
  // 2. LOGGING
  // =========================================================================
  /**
   * Central logger: writes to console, an optional on-screen panel, and
   * forwards to any consumer-registered 'log'/'error' callbacks.
   * @param {string} message
   * @param {boolean} [isError=false]
   */
  function log(message, isError) {
    if (isError) {
      console.error('[GenesisEmulator]', message);
    } else {
      console.log('[GenesisEmulator]', message);
    }

    if (state.statusLogEl) {
      const line = document.createElement('div');
      line.style.color = isError ? '#ff6b6b' : '#9fb0c9';
      line.textContent = message;
      state.statusLogEl.appendChild(line);
      state.statusLogEl.scrollTop = state.statusLogEl.scrollHeight;
    }

    if (state.callbacks.log) safeCall(state.callbacks.log, message, !!isError);
    if (isError && state.callbacks.error) safeCall(state.callbacks.error, message);
  }

  /** Invoke a consumer-supplied callback without letting it break the emulator. */
  function safeCall(fn, ...args) {
    try { fn(...args); } catch (e) { console.error('[GenesisEmulator] callback threw:', e); }
  }

  // =========================================================================
  // 3. UTILITIES
  // =========================================================================
  /** Decode a base64 string into a Uint8Array. */
  function base64ToBytes(b64) {
    const binary = atob(b64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }

  // =========================================================================
  // 4. DEFAULT UI (used for drop-in / iframe usage)
  // =========================================================================
  const THEME_CSS = `
    .ge-root { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      background:#0f1117; color:#e8eaf0; min-height:100vh; margin:0; padding:24px 16px 48px;
      display:flex; flex-direction:column; align-items:center; box-sizing:border-box; }
    .ge-root * { box-sizing:border-box; }
    .ge-h1 { font-size:1.3rem; font-weight:600; margin:0 0 4px; }
    .ge-sub { color:#8b90a0; margin:0 0 24px; font-size:0.85rem; text-align:center; max-width:520px; }
    .ge-panel { background:#1a1d27; border:1px solid #2a2e3a; border-radius:12px; padding:28px;
      width:100%; max-width:460px; text-align:center; }
    .ge-panel.ge-hidden { display:none; }
    .ge-drop { border:2px dashed #3a3f52; border-radius:10px; padding:32px 16px; cursor:pointer;
      transition:border-color .15s, background .15s; }
    .ge-drop:hover, .ge-drop.ge-drag { border-color:#4f8cff; background:rgba(79,140,255,.06); }
    .ge-drop p { margin:8px 0 0; color:#8b90a0; font-size:0.8rem; }
    .ge-btn { background:#4f8cff; color:#fff; border:none; padding:10px 20px; border-radius:8px;
      font-size:0.9rem; cursor:pointer; }
    .ge-btn:hover { background:#3d78ea; }
    .ge-filename { margin-top:14px; font-size:0.8rem; color:#8b90a0; word-break:break-all; }
    .ge-wrapper { width:100%; max-width:860px; }
    .ge-wrapper.ge-hidden { display:none; }
    .ge-topbar { display:flex; justify-content:space-between; align-items:center; margin-bottom:10px; }
    .ge-topbar span { color:#8b90a0; font-size:0.8rem; }
    .ge-back { background:transparent; color:#e8eaf0; border:1px solid #3a3f52; padding:6px 14px;
      border-radius:6px; cursor:pointer; font-size:0.8rem; }
    .ge-back:hover { border-color:#4f8cff; color:#4f8cff; }
    .ge-note { color:#8b90a0; font-size:0.72rem; margin-top:18px; max-width:460px; text-align:center; line-height:1.4; }
  `;

  /**
   * Builds the default drop-zone/file-picker UI into `mountPoint` and wires
   * it up to loadRom(). Used automatically unless the host page opts out
   * via `window.GenesisEmulatorNoAutoMount = true`.
   * @param {Element} mountPoint
   */
  function buildDefaultUI(mountPoint) {
    const styleTag = document.createElement('style');
    styleTag.textContent = THEME_CSS;
    document.head.appendChild(styleTag);

    const root = document.createElement('div');
    root.className = 'ge-root';
    root.innerHTML = `
      <div class="ge-h1">Genesis / Mega Drive Emulator</div>
      <p class="ge-sub">Runs entirely in your browser. Upload a ROM file you legally own to play.</p>
      <div class="ge-panel" id="ge-upload-panel">
        <div class="ge-drop" id="ge-drop-zone">
          <div style="font-size:2rem;">&#128193;</div>
          <button class="ge-btn" id="ge-choose-btn" type="button">Choose ROM file</button>
          <p>or drag and drop a .bin / .md / .gen / .smd file here</p>
        </div>
        <input type="file" id="ge-file-input" accept=".bin,.md,.gen,.smd" style="display:none;">
        <div class="ge-filename" id="ge-filename"></div>
      </div>
      <div class="ge-wrapper ge-hidden" id="ge-wrapper">
        <div class="ge-topbar">
          <span id="ge-game-name"></span>
          <button class="ge-back" id="ge-back-btn">&larr; Load a different ROM</button>
        </div>
      </div>
      <p class="ge-note">This page does not include or distribute any game ROMs. Only use ROM files you are legally entitled to.</p>
    `;
    mountPoint.appendChild(root);

    const uploadPanel = root.querySelector('#ge-upload-panel');
    const wrapper = root.querySelector('#ge-wrapper');
    const dropZone = root.querySelector('#ge-drop-zone');
    const fileInput = root.querySelector('#ge-file-input');
    const chooseBtn = root.querySelector('#ge-choose-btn');
    const filenameEl = root.querySelector('#ge-filename');
    const gameNameEl = root.querySelector('#ge-game-name');
    const backBtn = root.querySelector('#ge-back-btn');

    chooseBtn.addEventListener('click', () => fileInput.click());
    dropZone.addEventListener('click', () => fileInput.click());
    ['dragenter', 'dragover'].forEach(evt =>
      dropZone.addEventListener(evt, (e) => { e.preventDefault(); dropZone.classList.add('ge-drag'); }));
    ['dragleave', 'drop'].forEach(evt =>
      dropZone.addEventListener(evt, (e) => { e.preventDefault(); dropZone.classList.remove('ge-drag'); }));
    dropZone.addEventListener('drop', (e) => {
      const file = e.dataTransfer.files[0];
      if (file) handleFile(file);
    });
    fileInput.addEventListener('change', (e) => {
      const file = e.target.files[0];
      if (file) handleFile(file);
    });
    backBtn.addEventListener('click', () => location.reload());

    function handleFile(file) {
      filenameEl.textContent = `Loading: ${file.name} ...`;
      uploadPanel.classList.add('ge-hidden');
      wrapper.classList.remove('ge-hidden');
      gameNameEl.textContent = file.name;
      init(wrapper, { showStatusLog: true });
      loadRom(file);
    }
  }

  // =========================================================================
  // 5. ENGINE INJECTION
  // =========================================================================
  // We do NOT use <script src="blob:..."> or fetch() against blob:/data: URIs
  // for the engine's own files. Some environments (corporate security tools,
  // strict permissions policies) block one or both. Instead:
  //   - engine scripts are injected inline (script.textContent, not .src)
  //   - the WASM core, its report JSON, and the 7z decompressor are served
  //     straight from memory by patching EmulatorJS's downloadFile() method
  // This makes the whole load path immune to those restrictions.

  /** Injects the EmulatorJS engine scripts/CSS and patches its file loading. Runs once. */
  function injectEngine() {
    if (state.engineInjected) return;
    state.engineInjected = true;

    log('Injecting emulator engine scripts inline...');
    const order = ['emulator.js', 'nipplejs.js', 'shaders.js', 'storage.js',
                    'gamepad.js', 'GameManager.js', 'socket.io.min.js', 'compression.js'];
    for (const name of order) {
      const tag = document.createElement('script');
      tag.textContent = BUNDLE.scripts[name];
      document.head.appendChild(tag);
    }
    log('Engine scripts loaded.');

    const styleTag = document.createElement('style');
    styleTag.textContent = BUNDLE.css;
    document.head.appendChild(styleTag);

    patchDownloadFile();
  }

  /** Redirects EmulatorJS's downloadFile() to serve known assets from memory. */
  function patchDownloadFile() {
    const localAssets = {};
    for (const key in BUNDLE.data) {
      localAssets[key] = { bytes: base64ToBytes(BUNDLE.data[key].data) };
    }
    log('Core data assets decoded in memory: ' + Object.keys(localAssets).join(', '));

    const OriginalDownloadFile = window.EmulatorJS.prototype.downloadFile;
    window.EmulatorJS.prototype.downloadFile = function (path, progressCB, notWithPath, opts) {
      const basename = String(path).split('/').pop().split('?')[0];
      const asset = localAssets[basename];

      if (asset) {
        return new Promise((resolve) => {
          if (opts && opts.method === 'HEAD') {
            resolve({ headers: {} });
            return;
          }
          let data;
          if (basename.endsWith('.json')) {
            try {
              data = JSON.parse(new TextDecoder().decode(asset.bytes));
            } catch (e) {
              data = {};
            }
          } else {
            data = asset.bytes.buffer.slice(asset.bytes.byteOffset, asset.bytes.byteOffset + asset.bytes.byteLength);
          }
          resolve({ headers: {}, data });
        });
      }

      // Not a bundled asset (e.g. the ROM File itself) -- defer to the original.
      return OriginalDownloadFile.call(this, path, progressCB, notWithPath, opts).then((res) => {
        if (res === -1) {
          const kind = (path instanceof File) ? 'File' : (path instanceof Blob) ? 'Blob' : typeof path;
          log('downloadFile fallthrough FAILED: kind=' + kind + ', method=' + (opts && opts.method), true);
        }
        return res;
      });
    };
    log('Patched downloadFile() to serve core/report/decompressor files from memory.');
  }

  // =========================================================================
  // 6. PUBLIC API
  // =========================================================================
  const api = { init, loadRom, on, getInstance };

  /**
   * Mounts the emulator's player element into `target`.
   * @param {string|Element} target CSS selector or DOM element.
   * @param {{playerId?:string, showStatusLog?:boolean}} [options]
   * @returns {object} the GenesisEmulator API (chainable)
   */
  function init(target, options) {
    options = options || {};
    const el = (typeof target === 'string') ? document.querySelector(target) : target;
    if (!el) throw new Error('GenesisEmulator.init: target "' + target + '" not found');

    state.container = el;
    state.container.innerHTML = '';

    state.playerDiv = document.createElement('div');
    state.playerDiv.id = options.playerId || 'genesis-emulator-player';
    state.playerDiv.style.cssText = 'width:100%; aspect-ratio:4/3.2; background:#000; border-radius:8px; overflow:hidden;';
    state.container.appendChild(state.playerDiv);

    if (options.showStatusLog) {
      state.statusLogEl = document.createElement('div');
      state.statusLogEl.style.cssText =
        'margin-top:8px; background:#0a0c12; border:1px solid #2a2e3a; border-radius:8px; padding:10px 12px;' +
        'font-family:"SF Mono",Menlo,Consolas,monospace; font-size:0.72rem; max-height:160px; overflow-y:auto; white-space:pre-wrap;';
      state.container.appendChild(state.statusLogEl);
    } else {
      state.statusLogEl = null;
    }

    return api;
  }

  /**
   * Boots a ROM. Call init() first (skip this if using the built-in drop-in UI).
   * @param {File|Blob} file
   */
  function loadRom(file) {
    if (!state.container || !state.playerDiv) {
      throw new Error('GenesisEmulator.loadRom: call GenesisEmulator.init(target) first');
    }
    if (!(file instanceof Blob)) {
      throw new Error('GenesisEmulator.loadRom: expected a File or Blob, got ' + typeof file);
    }

    log('Loading ROM: ' + (file.name || '(unnamed)') + ' (' + file.size + ' bytes)');
    injectEngine();

    const config = {
      gameUrl: file,
      dataPath: './',
      system: 'segaMD',
      gameName: file.name || 'game',
      color: '#4f8cff',
      volume: 0.5,
      startOnLoad: true,
      backgroundColor: '#000000',
      threads: false
    };

    try {
      state.instance = new window.EmulatorJS('#' + state.playerDiv.id, config);
      state.instance.on('start', () => {
        log('Game started!');
        if (state.callbacks.start) safeCall(state.callbacks.start);
      });
      log('EmulatorJS instance created, booting core...');
    } catch (err) {
      log('Failed to create EmulatorJS instance: ' + err.message, true);
      throw err;
    }
  }

  /**
   * Registers a callback.
   * @param {'log'|'error'|'start'} event
   * @param {Function} callback
   * @returns {object} the GenesisEmulator API (chainable)
   */
  function on(event, callback) {
    if (!(event in state.callbacks)) throw new Error('GenesisEmulator.on: unknown event "' + event + '"');
    state.callbacks[event] = callback;
    return api;
  }

  /** @returns {?object} the underlying EmulatorJS instance, once booted. */
  function getInstance() {
    return state.instance;
  }

  window.GenesisEmulator = api;

  // =========================================================================
  // 7. AUTO-BOOTSTRAP
  // =========================================================================
  // Unless the host page opts out, build the default drop-in UI so this file
  // works standalone -- e.g. as the entire contents of an <iframe>'s page.
  function autoMount() {
    if (window.GenesisEmulatorNoAutoMount) return;
    buildDefaultUI(document.body);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', autoMount);
  } else {
    autoMount();
  }
})();

